<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center flex-wrap"><div><div class="text-overline">SALES CRM</div><h1 class="text-h5 font-weight-bold">Leads</h1><div class="grey--text">Track prospects from enquiry to conversion.</div></div><v-spacer/><v-btn v-if="$can('leads.create')" color="#165134" dark depressed @click="openCreate"><v-icon left>mdi-account-plus</v-icon>New Lead</v-btn></div></v-card><v-row class="mb-1"><v-col v-for="s in pipeline" :key="s.status" cols="6" sm="4" lg><v-card flat class="pipeline-card pa-3" @click="filterStatus(s.status)"><div class="d-flex align-center"><v-avatar size="36" :color="s.color" class="mr-3"><v-icon dark small>{{s.icon}}</v-icon></v-avatar><div><div class="caption grey--text">{{s.label}}</div><div class="text-h6 font-weight-bold">{{s.count}}</div></div></div></v-card></v-col></v-row><v-card flat class="pa-3 mb-4"><v-row dense align="center"><v-col cols="12" md="5"><v-text-field v-model="search" dense outlined clearable prepend-inner-icon="mdi-magnify" label="Search leads" @keyup.enter="load" @click:clear="load"/></v-col><v-col cols="12" md="3"><v-select v-model="status" :items="statuses" dense outlined clearable label="Status" @change="load"/></v-col><v-col cols="12" md="4" class="text-right"><v-chip class="mr-2">{{ total }} leads</v-chip><v-btn text @click="load"><v-icon left>mdi-refresh</v-icon>Refresh</v-btn></v-col></v-row></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading" :server-items-length="total" :options.sync="options" @update:options="load"><template v-slot:item.status="{item}"><v-chip x-small dark :color="statusColor(item.status)">{{ item.status }}</v-chip></template><template v-slot:item.priority="{item}"><v-chip x-small outlined>{{ item.priority || 'medium' }}</v-chip></template><template v-slot:item.actions="{item}"><v-btn v-if="$can('leads.edit')" icon small title="Edit lead" @click="edit(item)"><v-icon small>mdi-pencil</v-icon></v-btn><v-btn v-if="$can('site_visits.create') && item.status!=='lost'" icon small color="orange darken-2" title="Schedule site visit" @click="scheduleVisit(item)"><v-icon small>mdi-map-marker-plus</v-icon></v-btn><v-btn v-if="$can('leads.edit') && $can('customers.create') && !item.customer_id && item.status!=='lost'" icon small color="success" title="Convert to customer" @click="openConvert(item)"><v-icon small>mdi-account-convert</v-icon></v-btn><v-btn v-if="$can('sales.create') && item.customer_id" icon small color="#165134" title="Create booking" @click="createBooking(item)"><v-icon small>mdi-bookmark-plus</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="700"><v-card><v-card-title>{{ editing ? 'Edit Lead' : 'New Lead' }}<v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-form @submit.prevent="save"><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" outlined dense label="Name *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" outlined dense label="Phone *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" outlined dense label="Email"/></v-col><v-col cols="12" md="6"><v-select v-model="form.status" :items="editing&&editing.status==='converted'?statuses:editableStatuses" outlined dense label="Status" :disabled="editing&&editing.status==='converted'"/></v-col><v-col cols="12" md="6"><v-select v-model="form.priority" :items="priorities" outlined dense label="Priority"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.project_id" :items="projects" item-text="name" item-value="id" outlined dense clearable label="Interested Project" :loading="loadingProjects"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.budget" type="number" outlined dense label="Budget"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.next_follow_up" type="date" outlined dense label="Next Follow-up"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.assigned_to" :items="users" item-text="name" item-value="id" outlined dense clearable label="Assigned To" :loading="loadingUsers"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.source" outlined dense label="Source"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense rows="3" label="Notes"/></v-col></v-row></v-form></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn v-if="editing ? $can('leads.edit') : $can('leads.create')" color="#165134" dark :loading="saving" @click="save">Save Lead</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="convertDialog" max-width="560" persistent><v-card><v-card-title>Convert Lead to Customer</v-card-title><v-card-text><v-alert v-if="!duplicateCustomer" type="info" outlined dense>The lead details will be copied into a new customer profile. Existing site visits for this lead will also be linked to the customer.</v-alert><v-alert v-else type="warning" outlined dense><div class="font-weight-bold mb-1">Possible existing customer found</div><div>{{duplicateCustomer.name}} · {{duplicateCustomer.phone}}</div><div v-if="duplicateCustomer.email">{{duplicateCustomer.email}}</div><div class="caption mt-1">{{duplicateCustomer.customer_number}}</div></v-alert><div v-if="convertItem"><div class="font-weight-bold">{{convertItem.name}}</div><div class="grey--text">{{convertItem.phone}}<span v-if="convertItem.project"> · {{convertItem.project.name}}</span></div></div></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="converting" @click="closeConvert">Cancel</v-btn><v-btn v-if="duplicateCustomer" color="#165134" dark :loading="converting" @click="confirmConvert(duplicateCustomer.id)">Link Existing Customer</v-btn><v-btn v-else color="#165134" dark :loading="converting" @click="confirmConvert()">Convert Customer</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Leads',data(){return{loading:false,saving:false,dialog:false,convertDialog:false,converting:false,convertItem:null,duplicateCustomer:null,editing:null,search:'',status:null,total:0,pipelineCounts:{},items:[],projects:[],users:[],loadingProjects:false,loadingUsers:false,options:{page:1,itemsPerPage:15},statuses:['new','contacted','qualified','site_visit','negotiation','converted','lost'],editableStatuses:['new','contacted','qualified','site_visit','negotiation','lost'],priorities:['low','medium','high'],headers:[{text:'Lead #',value:'lead_number'},{text:'Name',value:'name'},{text:'Phone',value:'phone'},{text:'Source',value:'source'},{text:'Priority',value:'priority'},{text:'Status',value:'status'},{text:'Actions',value:'actions',sortable:false}],form:this.blank()}},computed:{pipeline(){const counts=this.pipelineCounts||{};const defs=[['new','New','grey','mdi-account-plus'],['contacted','Contacted','blue','mdi-phone'],['qualified','Qualified','indigo','mdi-account-check'],['site_visit','Site Visit','orange','mdi-map-marker'],['negotiation','Negotiation','purple','mdi-handshake'],['converted','Converted','success','mdi-check-circle']];return defs.map(function(d){return{status:d[0],label:d[1],color:d[2],icon:d[3],count:Number(counts[d[0]]||0)}})}},mounted(){this.load()},watch:{'$route.query.lead_id':function(){this.options.page=1;this.load()}},methods:{scheduleVisit(item){this.$router.push({name:'site-visits',query:{lead_id:item.id,customer_id:item.customer_id||''}})},createBooking(item){this.$router.push({name:'bookings',query:{customer_id:item.customer_id,sales_agent_id:item.assigned_to||'',project_id:item.project_id||''}})},openConvert(item){this.convertItem=item;this.duplicateCustomer=null;this.convertDialog=true},closeConvert(){this.convertDialog=false;this.convertItem=null;this.duplicateCustomer=null},async confirmConvert(customerId){if(!this.convertItem)return;this.converting=true;try{const payload=customerId?{customer_id:customerId}:{};const r=await api.post('/leads/'+this.convertItem.id+'/convert',payload);this.closeConvert();this.$root.$emit('show-success',r.data.message||'Lead converted successfully.');await this.load()}catch(e){if(e.response&&e.response.status===409&&e.response.data&&e.response.data.existing_customer){this.duplicateCustomer=e.response.data.existing_customer;this.$root.$emit('show-warning',e.response.data.message||'An existing customer was found.');return}this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to convert lead.')}finally{this.converting=false}},filterStatus(s){this.status=this.status===s?null:s;this.options.page=1;this.load()},blank(){return{name:'',phone:'',email:'',source:'',status:'new',priority:'medium',project_id:null,budget:null,next_follow_up:null,assigned_to:null,notes:''}},openCreate(){this.editing=null;this.form=this.blank();this.dialog=true;this.loadLookups()},edit(i){this.editing=i;this.form=Object.assign(this.blank(),i);this.dialog=true;this.loadLookups()},async loadLookups(){this.loadingProjects=true;this.loadingUsers=true;try{const[p,u]=await Promise.all([api.get('/projects',{params:{per_page:100}}),api.get('/sales-agents')]);this.projects=p.data.data||[];this.users=u.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load lead selections.')}finally{this.loadingProjects=false;this.loadingUsers=false}},async load(){this.loading=true;try{const r=await api.get('/leads',{params:{lead_id:this.$route.query.lead_id||null,search:this.search,status:this.status,page:this.options.page,per_page:this.options.itemsPerPage}});this.items=r.data.data||[];this.total=r.data.total||0;this.pipelineCounts=r.data.pipeline_counts||{}}finally{this.loading=false}},async save(){this.saving=true;try{if(this.editing)await api.put('/leads/'+this.editing.id,this.form);else await api.post('/leads',this.form);this.dialog=false;this.editing=null;await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to save lead.')}finally{this.saving=false}},statusColor(s){return{new:'grey',contacted:'blue',qualified:'indigo',site_visit:'orange',negotiation:'purple',converted:'success',lost:'error'}[s]||'grey'}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}.pipeline-card{border:1px solid rgba(22,81,52,.08);border-radius:14px!important;cursor:pointer;transition:.2s}.pipeline-card:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(20,50,35,.08)!important}</style>